static a_string ifc_string_copy_value(const a_string *source)
{ a_string result;edg_string_init_small(&result,source->allocator);edg_string_copy(&result,(a_string*)source);return result; }
static void *ifc_take_pointer(void **p) {void *result=*p;*p=NULL;return result;}
#define ifc_take_value(pointer) ({ __typeof__(*(pointer)) _ifc_taken=*(pointer); memset((pointer),0,sizeof(*(pointer))); _ifc_taken; })
#define IFC_ARRAY_PUSH(array,type,value) do { type _ifc_value=(value);Edg_array *_ifc_array=(array);edg_array_push(_ifc_array,&_ifc_value); } while(0)
static a_boolean ifc_tagged_equal(a_tagged_pointer a,a_tagged_pointer b) {return a.kind==b.kind && a.ptr==b.ptr;}
