static Opt_a_string ifc_opt_string_copy(const Opt_a_string *source) {
 Opt_a_string result={0};result.has_value=source->has_value;
 if(source->has_value)result.value=ifc_string_copy_value(&source->value);
 return result;
}
static void ifc_opt_string_destroy(Opt_a_string *source) {
 if(source->has_value)edg_string_destroy(&source->value);
 memset(source,0,sizeof(*source));
}
