static Opt_a_string name_from_index_an_ifc_text_offset(an_ifc_text_offset text_offset,
                                     a_symbol_locator *loc)
/*
An overload of name_from_index for an_ifc_text_offset types, see
name_from_index(an_ifc_name_index, a_symbol_locator*) for more information.
*/
{
  /* Convert the text offset into a name index. */
  an_ifc_name_index name_idx = {text_offset.file, ifc_ns_text_offset,
                             text_offset.value};

  return name_from_index_an_ifc_name_index(name_idx,loc);
}  /* name_from_index */


static a_boolean is_name_present(an_ifc_name_index name_idx)
/*
Return TRUE if the given IFC name index represents a name; otherwise, return
FALSE.
*/
{
  a_boolean result = TRUE;

  if (is_null_index(name_idx)) {
    result = FALSE;
  } else {
    Opt_a_string opt_name=name_from_index_an_ifc_name_index(name_idx,NULL);

    if ((opt_name).has_value && ((opt_name).value).len==0) {
      result = FALSE;
    }  /* if */
  
ifc_opt_string_destroy((Opt_a_string*)&opt_name);
}  /* if */
  return result;
}  /* is_name_present */


static a_boolean is_missing_source_location_an_ifc_source_line(const an_ifc_source_line line)
/*
Given an IFC source line, return TRUE if the source line represents a missing
source location; otherwise, return FALSE.
*/
{
  a_boolean          result = TRUE;
  an_ifc_line_number line_number = get_ifc_line(line);

  if ((line_number).value != 0) {
    result = FALSE;
  } else {
    an_ifc_name_index            file_idx = get_ifc_file(line);
    Opt_an_ifc_name_source_file opt_source_file={0};

    construct_node(&opt_source_file, file_idx);
    if ((opt_source_file).has_value) {
      an_ifc_name_source_file source_file = (opt_source_file).value;
      an_ifc_text_offset      path = get_ifc_path(source_file);
      an_ifc_text_offset      guard = get_ifc_guard(source_file);

      if ((path).value != 0 || (guard).value != 0) {
        result = FALSE;
      }  /* if */
    }  /* if */
  }  /* if */
  return result;
}  /* is_missing_source_location */


static a_boolean is_missing_source_location_an_ifc_line_offset(an_ifc_line_offset offset)
/*
Given an IFC line offset, return TRUE if the line represents a missing source
location; otherwise, return FALSE.
*/
{
  a_boolean               result = TRUE;
  Opt_an_ifc_source_line opt_src_line={0};

  construct_node(&opt_src_line, offset);
  if ((opt_src_line).has_value) {
    an_ifc_source_line src_line = (opt_src_line).value;

    result = is_missing_source_location_an_ifc_source_line(src_line);
  }  /* if */
  return result;
}  /* is_missing_source_location */


static a_boolean is_missing_source_location_an_ifc_source_location(
                                         const an_ifc_source_location src_loc)
/*
Given an IFC source location, return TRUE if the source location represents a
missing source location; otherwise, return FALSE.
*/
{
  return is_missing_source_location_an_ifc_line_offset(get_ifc_line(src_loc));
}  /* is_missing_source_location */


static a_boolean source_position_from_module(
                                       a_source_position          *pos,
                                       an_ifc_input_state         *input_state,
                                       an_ifc_index_type          file_idx,
                                       an_ifc_line_number_storage line,
                                       an_ifc_column_storage      column)
/*
Map the given IFC file index (the index of the file in the IFC
"name.source-file" partition), line (starting at 1; 0 is not accepted, a line
number must be given), and column (0 can be used for an unknown column number;
1 and above for the known column number) information for the given module input
state, into the source position at pos.  Return TRUE if processing succeeded,
otherwise return FALSE.
*/
{
  /* IFC LineNumbers start at one, a line number of zero means the source line
     isn't known.  As the front end (at the time of writing) doesn't support
     source locations for a file without a line, the caller is required to
     provide a line number. */
  check_assertion(line > 0);
  a_boolean     result = TRUE;
  a_module_sequence_number_mapping
                *msnmp = &input_state->sequence_numbers[file_idx];

  /* See if this file has been used before. */
  if (msnmp->starting_sequence_number == 0) {
    /* First time accessing this source file; record the start of a new
       source file.  Note that this may be out-of-order as it depends on the
       order that entities are used, but the full tree of source file
       references isn't available in the IFC file. */
    an_ifc_name_index src_file_idx={input_state->file,ifc_ns_name_source_file,file_idx};
    Opt_a_string opt_file_name=name_from_index_an_ifc_name_index(src_file_idx,NULL);

    if (!(opt_file_name).has_value) {
      { ifc_opt_string_destroy((Opt_a_string*)&opt_file_name); goto invalid; }
    }  /* if */

    a_string     file_name = ifc_string_copy_value(&((opt_file_name).value));
    a_const_char *copied_file_name = copy_string_to_region(
                                               FILE_SCOPE_REGION_NUMBER,
                                               edg_string_chars(&(file_name)));
    record_inclusion_of_module_source_file(
                                         copied_file_name, pos,
                                         input_state->import_decl->module_info,
                                         msnmp->max_line_number);
    msnmp->starting_sequence_number = pos->seq;
  
edg_string_destroy((a_string*)&file_name);
ifc_opt_string_destroy((Opt_a_string*)&opt_file_name);
}  /* if */
  /* If this assertion fails, the initial source position scan when the
     module is imported did not properly account for it. */
  check_assertion(line <= msnmp->max_line_number);
  pos->seq = msnmp->starting_sequence_number + line;
  pos->column = (a_column_number)column;
#if FULLY_RESOLVED_MACRO_POSITIONS
  pos->orig_seq = pos->seq;
  pos->orig_column = pos->column;
#endif /* FULLY_RESOLVED_MACRO_POSITIONS */
  goto done;
invalid:
  result = FALSE;
done:
  return result;
}  /* source_position_from_module */


static a_boolean source_position_from_locus(
                                           a_source_position            *pos,
                                           const an_ifc_source_location locus)
/*
Map the IFC locus source position information into the source position at pos.
Return TRUE if processing succeeded, otherwise return FALSE.
*/
{
  a_boolean               result = TRUE;
  Opt_an_ifc_source_line opt_isl={0};
  an_ifc_line_offset      line_offset = get_ifc_line(locus);

  construct_node(&opt_isl, line_offset);
  if ((opt_isl).has_value) {
    an_ifc_source_line isl = (opt_isl).value;
    an_ifc_line_number line = get_ifc_line(isl);

    if ((line).value == 0) {
      /* IFC LineNumbers start at one, a line number of zero means the source
         line isn't known.  As the front end (at the time of writing) doesn't
         support source locations for a file without a line, resolve all cases
         of this to null source position. */
      *pos = null_source_position;
    } else {
      an_ifc_name_index file_idx = get_ifc_file(isl);

      if (file_idx.sort != ifc_ns_name_source_file) {
        a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"expected "); { a_string _ifc_owned_piece=(index_to_str_an_ifc_name_index(file_idx)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } edg_string_append_cstr(&_ifc_string_result," to be "); edg_string_append_cstr(&_ifc_string_result,str_for_an_ifc_name_sort(ifc_ns_name_source_file)); _ifc_string_result; });

        ifc_unexpected(module_of(file_idx), edg_string_chars(&(err_msg)));
        { edg_string_destroy((a_string*)&err_msg); goto invalid; }
      
edg_string_destroy((a_string*)&err_msg);
}  /* if */

      /* Add one to map 0-based IFC column numbers to 1-based EDG numbers. */
      an_ifc_column_storage column = (get_ifc_column(locus)).value + 1;
      result = source_position_from_module(pos, input_state_for(isl),
                                           file_idx.value, (line).value, column);
    }  /* if */
  }  /* if */
  goto done;
invalid:
  result = FALSE;
done:
  return result;
}  /* source_position_from_locus */



/*
An RAII type representing a source position hint formed from an IFC locus.
This type ensures that the token cache does not hold onto a position hint
beyond the lifetime of the hint.
*/
struct an_ifc_source_position_hint {
a_module_token_cache_ptr
                cache_ptr;
a_source_position
                pos;
a_boolean     hint_given;
};

static a_source_position_ptr an_ifc_source_position_hint_as_pos(an_ifc_source_position_hint *self)
{ return &self->pos; };  /* an_ifc_source_poisiton_hint */


static void an_ifc_source_position_hint_init(an_ifc_source_position_hint *self, 
                                           a_module_token_cache_ptr     cache,
                                           const an_ifc_source_location locus)
{
memset(self,0,sizeof(*self));
self->cache_ptr = cache;
self->hint_given = TRUE;

  source_position_from_locus(&self->pos, locus);
  a_module_token_cache_suggest_source_position(self->cache_ptr,&self->pos);
}  /* an_ifc_source_position_hint::an_ifc_source_position_hint */




static inline a_boolean index_has_locus_an_ifc_decl_index(an_ifc_decl_index idx)
/*
Given an IFC index, return TRUE if the index has an associated locus;
otherwise, return FALSE.
*/
{
  a_boolean result = TRUE;

  if (is_null_index(idx)) {
    result = FALSE;
  } else {
    an_ifc_decl_sort sort=idx.sort;

    if (!has_partition_kind_an_ifc_decl_sort(sort)) {
      result = FALSE;
    } else if (!validate(idx)) {
      result = FALSE;
    } else if (!has_ifc_locus(idx)) {
      result = FALSE;
    }  /* if */
  }  /* if */
  return result;
}


