static void an_ifc_source_position_hint_destroy(an_ifc_source_position_hint *self)
{
  if (self->hint_given && a_module_token_cache_get_position_hint(self->cache_ptr) == &self->pos) {
    a_module_token_cache_set_position_hint(self->cache_ptr,NULL);
  }  /* if */
}  /* an_ifc_source_position_hint::~an_ifc_source_position_hint */

