static inline a_module_ptr get_module_with_purview_of_an_ifc_decl_index(an_ifc_decl_index index)
/*
Return the module that the given declaration index is in the purview of.  If
the declaration is in the purview of the global module, NULL is returned.
*/
{
  a_module_ptr result = skip_module_partitions(module_of(index));

  if (result->kind == mk_header_unit) {
    result = NULL;
  } else if (has_ifc_specifiers(index) && validate(index)) {
    an_ifc_basic_specifiers_bitfield specifiers = get_ifc_specifiers(index);

    if (test_bitmask_ifc_bsb_is_member_of_global_module(specifiers)) {
      result = NULL;
    }  /* if */
  }  /* if */
  return result;
}  /* get_module_with_purview_of */


static inline a_module_ptr get_module_with_purview_of_an_ifc_macro_index(an_ifc_macro_index index)
/*
Return NULL as all macros are in the purview of the global module.
*/
{
  return NULL;
}  /* get_module_with_purview_of */


static inline a_module_entity_ptr
get_ifc_basic_module_entity(an_ifc_decl_index index)
/*
Return the module entity corresponding to the given IFC declaration index.
This function is provided as part of the implementation of
get_ifc_module_entity, prefer get_ifc_module_entity in other cases.
*/
{
  a_module_entity_ptr      result = NULL;
  Opt_a_symbol_header_ptr opt_decl_name_sym=get_name_symbol(index);

  if ((opt_decl_name_sym).has_value) {
    a_module_ptr          mod = get_module_with_purview_of_an_ifc_decl_index(index);
    a_module_entity_scope *mesp =
                        get_ifc_module_entity_scope(get_ifc_home_scope(index));
    a_symbol_header_ptr   decl_name_sym = (opt_decl_name_sym).value;

    result = get_module_entity(mod, mesp, decl_name_sym);
  }  /* if */
  return result;
}  /* get_ifc_basic_module_entity */


