/*
This class implements a lazily-loadable function parameter chart abstraction
(i.e., the chart remains unloaded until information about a parameter is
requested).
*/
struct a_lazy_ifc_func_param_chart {
an_ifc_chart_index
                chart_idx;
Opt_an_ifc_chart_unilevel opt_node;
a_boolean     node_invalid;
};

static void a_lazy_ifc_func_param_chart_init(a_lazy_ifc_func_param_chart *self, an_ifc_chart_index chart_idx_val)
{
memset(self,0,sizeof(*self));
self->chart_idx = chart_idx_val;
self->node_invalid = FALSE;
};  /* a_lazy_ifc_func_param_chart */

/*
This class implements a "function parameter context" which abstracts away the
various locations the IFC stores parameter information to provide a consistent
view of the "best" information the IFC provides.

This type is implemented in terms of relative indexes to allow for maximum
flexibility (given the current IFC status-quo's potential for mismatched
information).
*/
struct an_ifc_func_param_context {
an_ifc_index_type
                num_params;
an_ifc_type_index
                params_type;
a_lazy_ifc_func_param_chart
                decl_param_chart;
a_lazy_ifc_func_param_chart
                def_param_chart;
a_lazy_ifc_func_param_chart
                msvc_traits_param_chart;
a_lazy_ifc_func_param_chart
                parameterizer_msvc_traits_param_chart;
};

static an_ifc_index_type an_ifc_func_param_context_get_num_params(an_ifc_func_param_context *self)
{ return self->num_params; };  /* an_ifc_func_param_context */

/*
An RAII type representing a module isolation scope.  This type should be
used to manage the lifetime of a sck_module_isolated scope.
*/
struct a_module_isolation_scope {
a_memory_region_number
                region_to_switch_back_to;
};

;  /* a_module_isolation_scope */


static void a_module_isolation_scope_init(a_module_isolation_scope *self)
{
memset(self,0,sizeof(*self));

  /* Switch to the file scope memory region to prevent IL entries within
     internal entity hashing maps from being allocated into a short-lived
     memory region (and then freed as part of memory region management). */
  switch_to_file_scope_region(&self->region_to_switch_back_to);
  (void)push_scope(sck_module_isolated, NO_SCOPE_NUMBER, /*assoc_type=*/NULL,
                   /*assoc_routine=*/NULL);
}  /* a_module_isolation_scope::a_module_isolation_scope */


static void a_module_isolation_scope_destroy(a_module_isolation_scope *self)
{
  pop_scope();
  switch_back_to_original_region(self->region_to_switch_back_to);
}  /* a_module_isolation_scope::~a_module_isolation_scope */


/*
The template module isolation scope class extends the module isolation scope.
It additionally encapsulates the construction of a detached template parameter
list and isolates the template parameter resolution (in
find_template_parameter).  This prevents resolution of template parameters to
an incorrect parameter higher up in the scope stack.

See alloc_detached_templ_param_sym for more information about detached template
parameters.
*/

struct Template_module_isolation_scope_an_ifc_decl_template {
a_memory_region_number
                region_to_switch_back_to;
};

;

struct Template_module_isolation_scope_an_ifc_decl_partial_specialization {
a_memory_region_number
                region_to_switch_back_to;
};

;

