                 spec_decl = (opt_spec_decl).value;
    a_template_arg_ptr templ_args=create_templ_args_for_comparison_an_ifc_decl_specialization_args1(spec_decl);
    a_module_ptr mod = get_module_with_purview_of_an_ifc_decl_index(index);
    a_module_entity_scope
                 *mesp =
                        get_ifc_module_entity_scope(get_ifc_home_scope(index));
    a_symbol_header_ptr
                 decl_name_sym = (opt_decl_name_sym).value;
    an_ifc_decl_index
                 parameterized_idx = get_ifc_decl(spec_decl);

