static void f_emit_not_a_module_entity_error(int               line_number,
                                             a_const_char      *function,
                                             an_ifc_decl_index index)
/*
The given declaration index is not a module entity but the front end tried to
use it as one; emit an appropriate diagnostic.  The given line number and
function values respectively are the line number and function where the misuse
occurred.
*/
{
  a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"Unexpected attempt to represent "); { a_string _ifc_owned_piece=(index_to_str_an_ifc_decl_index(index)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } edg_string_append_cstr(&_ifc_string_result," as a module entity"); _ifc_string_result; });

  ifc_requirement_cstr(line_number,function,module_of(index),FALSE,edg_string_chars(&(err_msg)));

edg_string_destroy((a_string*)&err_msg);
}  /* f_emit_not_a_module_entity_error */


#define emit_not_a_module_entity_error(index) \
  f_emit_not_a_module_entity_error(__LINE__, __EDG_func__, (index))


