static an_ifc_decl_index get_ifc_enclosing_namespace_scope(
                                                    an_ifc_decl_index decl_idx)
/*
Return the associated IFC index for the scope of the given declaration.  If no
enclosing namespace scope can be determined, return a null IFC index.
*/
{
  an_ifc_decl_index result={0};
  an_ifc_decl_index home_scope_idx = get_ifc_home_scope(decl_idx);

  while (!is_namespace_scope_an_ifc_decl_index(home_scope_idx)) {
    if (!validate(home_scope_idx) || !has_ifc_home_scope(home_scope_idx)) {
      goto invalid;
    }  /* if */

    an_ifc_decl_index prev_home_scope_idx = home_scope_idx;
    home_scope_idx = get_ifc_home_scope(home_scope_idx);
    if (an_ifc_decl_index_equal(home_scope_idx,prev_home_scope_idx)) {
      /* Detect the unlikely case of a cycle. */
      a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"The enclosing namespace scope of "); { a_string _ifc_owned_piece=(index_to_str_an_ifc_decl_index(decl_idx)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } edg_string_append_cstr(&_ifc_string_result," could not be resolved due to a cyclic relationship"); _ifc_string_result; });

      ifc_unexpected(module_of(decl_idx), err_msg);
      { edg_string_destroy((a_string*)&err_msg); goto invalid; }
    
edg_string_destroy((a_string*)&err_msg);
}  /* if */
  }  /* while */
  result = home_scope_idx;
invalid:
  return result;
}  /* get_ifc_enclosing_namespace_scope */


static void issue_unsupported_construct_error(a_module_ptr      mod,
                                              a_const_char      *node,
                                              a_source_position *pos)
/*
Issue an error that an unhandled node was encountered in the given module.
node is the textual representation of the problematic node.  pos is the source
position associated with the diagnostic.  Call this function when encountering
unsupported IFC nodes.
*/
{
  if (!mod->contains_unsupported_constructs) {
    error(ec_module_file_contains_unsupported_constructs, mod);
    mod->contains_unsupported_constructs = TRUE;
  }  /* if */
  pos_error(ec_unhandled_ifc_construct, pos, node);
}  /* issue_unsupported_construct_error */



