    case ifc_tos_msvc_confusion:
    case ifc_tos_msvc_confused_choice:
    case ifc_tos_msvc_confused_push_state:
      { a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,str_for_an_ifc_triadic_operator_sort(op)); edg_string_append_cstr(&_ifc_string_result," is not a supported TriadicOperator"); _ifc_string_result; });

        ifc_unexpected(mod, err_msg);
      
edg_string_destroy((a_string*)&err_msg);
}
      break;
    case ifc_tos_choice:
    case ifc_tos_construct_at:
    case ifc_tos_initialize:
      kind = opkind_other;
      break;
    default_is_unexpected_str("Unexpected TriadicOperator");
