/*
This struct is used to represent an individual lazily-loadable part of an
entity (e.g., an initializer, definition, etc).

The normal flow is:

  1. An entity is first associated with the corresponding IFC declaration via a
     call to associate_entity.
  2. A call to load the entity is made (from somewhere like interpret.c).
  3. A call is made (prior to processing) to can_be_processed to detect
     unresolvable cycles and avoid repeating potentially expensive work
     (that previously failed).
  4. If the entity processing is started, mark_pending is called.
  5. When the entity part is completely processed, mark_finished or
     mark_failure is called (respectively depending on success or failure of
     processing).

Multiple copies of this struct are used rather than having one universal
(singleton) instance to allow for multiple pieces of the same entity to be
independently loaded.
*/
struct a_lazy_entity_part {
ifc_Ptr_map_a_tagged_pointer_an_ifc_decl_index
                availible_definitions;
ifc_Small_dyn_array_a_tagged_pointer_10
                pending_entities;
ifc_Ptr_set_a_tagged_pointer
                *bad_entities;

a_tagged_pointer pending_entities_buffer[10];
};

static void a_lazy_entity_part_init(a_lazy_entity_part *self)
{
memset(self,0,sizeof(*self));
ifc_Ptr_map_a_tagged_pointer_an_ifc_decl_index_init(&self->availible_definitions,10);
edg_array_init_buffer(&self->pending_entities,sizeof(a_tagged_pointer),EDG_ALLOC_FE,0,NULL,NULL,self->pending_entities_buffer,10);

}

static void a_lazy_entity_part_associate_entity(a_lazy_entity_part *self, a_tagged_pointer ptr, an_ifc_decl_index decl_idx)
{ ifc_Ptr_map_a_tagged_pointer_an_ifc_decl_index_map_or_replace(&(self->availible_definitions),ptr,decl_idx); }

static a_boolean a_lazy_entity_part_has_associated_ifc_decl(a_lazy_entity_part *self, a_tagged_pointer ptr)
{ return !is_null_index(ifc_Ptr_map_a_tagged_pointer_an_ifc_decl_index_get(&(self->availible_definitions),ptr)); }

static an_ifc_decl_index a_lazy_entity_part_get_associated_ifc_decl(a_lazy_entity_part *self, a_tagged_pointer ptr)
{ return ifc_Ptr_map_a_tagged_pointer_an_ifc_decl_index_get(&(self->availible_definitions),ptr); }

static a_boolean a_lazy_entity_part_can_be_processed(a_lazy_entity_part *self, a_tagged_pointer ptr)
{ return !a_lazy_entity_part_is_pending(self,ptr) && !a_lazy_entity_part_is_failed(self,ptr); }

static void a_lazy_entity_part_mark_pending(a_lazy_entity_part *self, a_tagged_pointer ptr)
{ a_lazy_entity_part_add_to_pending_set(self,ptr); }

static a_boolean a_lazy_entity_part_is_failed(a_lazy_entity_part *self, a_tagged_pointer ptr)
{ return self->bad_entities != NULL && ifc_Ptr_set_a_tagged_pointer_contains(self->bad_entities,ptr); };  /* a_lazy_entity_part */


static void a_lazy_entity_part_destroy(a_lazy_entity_part *self)
{
  if (self->bad_entities != NULL) {
    free_fe(self->bad_entities,sizeof(*(self->bad_entities)));
  }  /* if */

edg_map_destroy(&self->availible_definitions);
edg_array_destroy(&self->pending_entities);
}  /* a_lazy_entity_part::~a_lazy_entity_part */


static a_boolean a_lazy_entity_part_is_pending(a_lazy_entity_part *self, a_tagged_pointer ptr)
{
  for(size_t _ifc_iteration_62=0;_ifc_iteration_62<(&(self->pending_entities))->len;++_ifc_iteration_62) {
a_tagged_pointer other_ptr=*(a_tagged_pointer *)edg_array_at(&(self->pending_entities),_ifc_iteration_62);

    if (ifc_tagged_equal(other_ptr,ptr)) {
      return TRUE;
    }  /* if */
  
}  /* for */
  return FALSE;
}  /* is_pending */


static void a_lazy_entity_part_mark_finished(a_lazy_entity_part *self, a_tagged_pointer ptr)
{
  a_lazy_entity_part_remove_from_pending_set(self,ptr);
  ifc_Ptr_map_a_tagged_pointer_an_ifc_decl_index_unmap(&(self->availible_definitions),ptr);
}  /* a_lazy_entity_part::mark_finished */


static void a_lazy_entity_part_mark_failure(a_lazy_entity_part *self, a_tagged_pointer ptr)
{
  /* There should be at least one failure reported if an entity is being marked
     as failed. */
  check_assertion(is_at_least_one_error());
  a_lazy_entity_part_remove_from_pending_set(self,ptr);
  if (self->bad_entities == NULL) {
    self->bad_entities = ({ ifc_Ptr_set_a_tagged_pointer *_ifc_new=(ifc_Ptr_set_a_tagged_pointer *)alloc_fe(sizeof(ifc_Ptr_set_a_tagged_pointer)); ifc_Ptr_set_a_tagged_pointer_init(_ifc_new,10u); _ifc_new; });
  }  /* if */
  ifc_Ptr_set_a_tagged_pointer_add(self->bad_entities,ptr);
}  /* a_lazy_entity_part::mark_failure */


static void a_lazy_entity_part_add_to_pending_set(a_lazy_entity_part *self, a_tagged_pointer ptr)
{
  IFC_ARRAY_PUSH(&(self->pending_entities),a_tagged_pointer,ptr);
}  /* a_lazy_entity_part::add_to_pending_set */


static void a_lazy_entity_part_remove_from_pending_set(a_lazy_entity_part *self, a_tagged_pointer ptr)
{
  /* Check from back to front as typically the most recently added pending
     entity is the one being referenced. */
  for (size_t r = (&(self->pending_entities))->len; r > 0; --r) {
    size_t i = r - 1;

    if (ifc_tagged_equal((*(a_tagged_pointer *)edg_array_at(&(self->pending_entities),i)),ptr)) {
      edg_array_remove(&(self->pending_entities),i,1);
      break;
    }  /* if */
  }  /* for */
}  /* a_lazy_entity_part::remove_from_pending_set */


