static a_boolean map_pending_routine_definitions(an_ifc_decl_index decl_idx,
                                                 a_routine_ptr     rp)
/*
Given a declaration index representing a function-like entity, and the
corresponding IL entity (i.e., routine pointer), map the associated IL entity
to any associated function definitions.

Return TRUE if a definition for the function was recorded; otherwise, return
FALSE.
*/
{
  a_boolean result = FALSE;

  switch (decl_idx.sort) {
    case ifc_ds_decl_constructor:
      { an_ifc_decl_constructor ctor_decl={0};

        construct_node_prechecked(&ctor_decl, decl_idx);
        result = try_map_routine_definition_an_ifc_decl_constructor(ctor_decl,decl_idx,rp);
      }
      break;
    case ifc_ds_decl_destructor:
      { an_ifc_decl_destructor dtor_decl={0};

        construct_node_prechecked(&dtor_decl, decl_idx);
        result = try_map_routine_definition_an_ifc_decl_destructor(dtor_decl,decl_idx,rp);
      }
      break;
    case ifc_ds_decl_function:
      { an_ifc_decl_function func_decl={0};

        construct_node_prechecked(&func_decl, decl_idx);
        result = try_map_routine_definition_an_ifc_decl_function(func_decl,decl_idx,rp);
      }
      break;
    case ifc_ds_decl_method:
      { an_ifc_decl_method method_decl={0};

        construct_node_prechecked(&method_decl, decl_idx);
        result = try_map_routine_definition_an_ifc_decl_method(method_decl,decl_idx,rp);
      }
      break;
    case ifc_ds_decl_specialization:
      { an_ifc_decl_specialization spec_decl={0};

        construct_node_prechecked(&spec_decl, decl_idx);

        an_ifc_specialization_sort
                specialization_sort = get_ifc_sort(spec_decl);
        a_boolean
                is_instantiation = specialization_sort == ifc_ss_instantiation;
        /* Check to make sure this is not an instantiation; instantiations do
           not have their own definitions. */
        if (!is_instantiation) {
          an_ifc_decl_index parameterized_idx = get_ifc_decl(spec_decl);

          result = map_pending_routine_definitions(parameterized_idx, rp);
        }  /* if */
      }
      break;
    case ifc_ds_decl_intrinsic:
      /* This is a no op, intrinsic functions do not have user defined
         bodies. */
      break;
    case ifc_ds_decl_reference:
      /* FIXME: For now, consider this a no op; we may want to consider using
         collapse_partition_index to make this case disappear (by making the
         module entity pointer for a DeclReference resolve to the referenced
         declaration's module entity pointer). */
      break;
    case ifc_ds_decl_using_declaration:
      /* FIXME: For now, consider this a no op; we may want to map these to the
         aliased entity a bit more explicitly. */
      break;
    default:
#if CHECKING
      /* When this condition is violated the front end has mapped the IFC
         representation to an IL entity while the IFC representation doesn't
         suggest any known way the IFC encodes a function-like entity.  There's
         either an unhandled case, or the module entity should've been
         invalidated (for resulting in the wrong IL entity kind). */
      { a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); { a_string _ifc_owned_piece=(index_to_str_an_ifc_decl_index(decl_idx)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } edg_string_append_cstr(&_ifc_string_result," is represented in the IL"
                         " as a routine"); _ifc_string_result; });

        unexpected_condition_str(edg_string_chars(&(err_msg)));
      
edg_string_destroy((a_string*)&err_msg);
}
#endif /* CHECKING */
      break;
  }  /* switch */
  return result;
}  /* map_pending_routine_definitions */


static void record_pending_ifc_template_specializations(
                                                    a_template_ptr    templ,
                                                    an_ifc_decl_index decl_idx)
/*
Record the information needed to retrieve a definition for templ if it turns
out to be needed later on.
*/
{
  /* Ensure the canonical template IL entity is what's being mapped onto. */
  check_assertion(templ != NULL && templ->canonical_template != NULL);
  templ = templ->canonical_template;
  a_lazy_entity_part_associate_entity(ifc_template_specializations,make_tagged_ptr(templ),decl_idx);
}  /* record_pending_ifc_template_specializations */







static a_boolean is_local_variable_symbol(a_symbol_ptr sym)
/*
Given a symbol, return TRUE if it's a symbol for a local variable; otherwise,
return FALSE.
*/
{
  a_boolean result = FALSE;

  if (sym->kind == sk_variable) {
    a_variable_ptr var = variable_for_symbol(sym);

    result = var->source_corresp.is_local_to_function;
  }  /* if */
  return result;
}  /* is_local_variable_symbol */

#if CHECKING

static a_boolean is_nested_class_member(a_module_entity_ptr mep)
/*
Given a module entity pointer, return TRUE if mep->scope is a nested class;
otherwise, return FALSE.
*/
{
  a_boolean result = FALSE;

  if (mep->scope != NULL) {
    a_scope_ptr scope = mep->scope;
    a_scope_ptr parent_scope = scope->parent;

    if (scope->kind == sck_class_struct_union && parent_scope != NULL) {
      if (parent_scope->kind == sck_class_struct_union) {
        result = TRUE;
      }  /* if */
    }  /* if */
  }  /* if */
  return result;
}  /* is_nested_class_member */


static a_boolean is_in_explicit_specialization(a_module_entity_ptr mep)
/*
Given a module entity pointer, return TRUE if mep->scope has an associated
template class; otherwise, return FALSE.
*/
{
  a_boolean result = FALSE;

  if (mep->scope != NULL) {
    a_scope_ptr scope = mep->scope;

    if (scope->kind == sck_class_struct_union) {
      a_type_ptr type = scope->variant.assoc_type;
      a_class_type_supplement_ptr extra_info = class_type_supp(type);

      if (extra_info->assoc_template != NULL ||
          extra_info->template_arg_list != NULL) {
        result = TRUE;
      }  /* if */
    }  /* if */
  }  /* if */
  return result;
}  /* is_in_explicit_specialization */

#endif /* CHECKING */

static a_boolean is_function_hidden_friend(const an_ifc_decl_function decl)
/*
Return TRUE if the given function is a hidden friend; otherwise, return FALSE.
*/
{
  an_ifc_function_traits_bitfield traits = get_ifc_traits(decl);

  return test_bitmask_ifc_ftb_hidden_friend(traits);
}  /* is_function_hidden_friend */


static a_boolean is_hidden_friend_an_ifc_decl_index(an_ifc_decl_index decl_idx)
/*
Return TRUE if the declaration indexed by the given declaration index is a
hidden friend function; otherwise, return FALSE.
*/
{
  a_boolean result = FALSE;

  if (decl_idx.sort == ifc_ds_decl_function) {
    Opt_an_ifc_decl_function opt_func_decl={0};

    construct_node(&opt_func_decl, decl_idx);
    if ((opt_func_decl).has_value) {
      an_ifc_decl_function func_decl = (opt_func_decl).value;

      if (is_function_hidden_friend(func_decl)) {
        result = TRUE;
      }  /* if */
    }  /* if */
  } else if (decl_idx.sort == ifc_ds_decl_template) {
    Opt_an_ifc_decl_template opt_templ_decl={0};

    construct_node(&opt_templ_decl, decl_idx);
    if ((opt_templ_decl).has_value) {
      an_ifc_decl_template templ_decl = (opt_templ_decl).value;
      an_ifc_decl_index    entity_decl_idx =
                                  get_ifc_decl(get_ifc_entity(templ_decl));

      if (is_hidden_friend_an_ifc_decl_index(entity_decl_idx)) {
        result = TRUE;
      }  /* if */
    }  /* if */
  }  /* if */
  return result;
}  /* is_hidden_friend */


static a_boolean is_hidden_friend_an_ifc_decl_friend(const an_ifc_decl_friend friend_decl)
/*
Return TRUE if the given declaration is a hidden friend function; otherwise,
return FALSE.
*/
{
  a_boolean         result = FALSE;
  an_ifc_expr_index friend_expr_id = get_ifc_entity(friend_decl);

  if (friend_expr_id.sort == ifc_es_expr_named_decl) {
    Opt_an_ifc_expr_named_decl opt_named_decl_expr={0};

    construct_node(&opt_named_decl_expr, friend_expr_id);
    if ((opt_named_decl_expr).has_value) {
      an_ifc_expr_named_decl named_decl_expr = (opt_named_decl_expr).value;
      an_ifc_decl_index      named_decl_idx =
                                       get_ifc_resolution(named_decl_expr);
      if (is_hidden_friend_an_ifc_decl_index(named_decl_idx)) {
        result = TRUE;
      }  /* if */
    }  /* if */
  }  /* if */
  return result;
}  /* is_hidden_friend */


static an_ifc_decl_index get_hidden_friend_decl_index(
                                         const an_ifc_decl_friend friend_decl)
/*
Return the declaration index of the hidden friend represented by the given
friend declaration.  Note that the caller is responsible for checking if the
given IFC friend declaration represents a hidden friend via is_hidden_friend.
*/
{
  an_ifc_expr_index friend_expr_id = get_ifc_entity(friend_decl);
  /* This should always hold per the logic in is_hidden_friend. */
  check_assertion(friend_expr_id.sort == ifc_es_expr_named_decl);

  an_ifc_expr_named_decl named_decl_expr={0};
  construct_node_prechecked(&named_decl_expr, friend_expr_id);
  return get_ifc_resolution(named_decl_expr);
}  /* get_hidden_friend_decl_index */


static void associate_symbol_with_declaration(an_ifc_decl_index decl_idx,
                                              a_symbol_ptr      sym)
/*
Associate the given symbol with the given declaration.  This function is used
to populate the ifc_decl_lookup_table and provide a resolution of the symbol
given the declaration.
*/
{
  size_t hash=ifc_hash_an_ifc_decl_index(&decl_idx);
  a_symbol_ptr prev_sym = ifc_Ptr_map_an_ifc_decl_index_a_symbol_ptr_get_with_hash(ifc_decl_lookup_table,decl_idx,hash);

  if (prev_sym != sym) {
    if (prev_sym != NULL) {
      a_string_view prev_sym_str=edg_string_view(prev_sym->header->identifier,
                                 prev_sym->header->identifier_length);
      a_string_view sym_str=edg_string_view(sym->header->identifier,
                            sym->header->identifier_length);
      a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"Unexpected redefinition of the associated symbol "
                            "for "); { a_string _ifc_owned_piece=(index_to_str_an_ifc_decl_index(decl_idx)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } edg_string_append_cstr(&_ifc_string_result," from \""); edg_string_append_view(&_ifc_string_result,prev_sym_str); edg_string_append_cstr(&_ifc_string_result,"\" to \""); edg_string_append_view(&_ifc_string_result,sym_str); edg_string_append_cstr(&_ifc_string_result,"\""); _ifc_string_result; });

      ifc_unexpected(module_of(decl_idx), edg_string_chars(&(err_msg)));
    
edg_string_destroy((a_string*)&err_msg);
}  /* if */
    ifc_Ptr_map_an_ifc_decl_index_a_symbol_ptr_map_or_replace_with_hash(ifc_decl_lookup_table,decl_idx,sym,hash);
  }  /* if */
}  /* associate_symbol_with_declaration */


void record_symbol_for_ifc_decl(a_symbol_ptr  sym)
/*
The current token is a tok_ifc_decl token.  Map its associated IFC declaration
index information to the given symbol.
*/
{
  an_ifc_decl_index decl_idx =
               from_lexical_index_an_ifc_decl_index(ifc_index_for_curr_token);

#if DEBUG
  if (db_flag_is_set("ifc_idx")) {
    a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"Bound token resolved for "); { a_string _ifc_owned_piece=(index_to_str_an_ifc_decl_index(decl_idx)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } _ifc_string_result; });

    edg_string_print(&(err_msg),f_debug,"\n");
  
edg_string_destroy((a_string*)&err_msg);
}  /* if */
#endif /* DEBUG */
  associate_symbol_with_declaration(decl_idx, sym);

  /* Associate the appropriate module entity with this symbol's IL entity. */
  a_module_entity_ptr mep = get_ifc_module_entity(decl_idx);
  if (sym->kind == sk_overloaded_function) {
    mep->entity.kind = iek_il_entity_list_entry;

    a_symbol_ptr overloaded_sym = sym->variant.overloaded_function.symbols;
    do {
      an_il_entity_list_entry_ptr ielep = alloc_il_entity_list_entry();
      an_il_entry_kind            kind;
      char                        *il_entity = il_entry_for_symbol_null_okay(
                                                                overloaded_sym,
                                                                &kind);
      /* Convert the symbol to an IL entity list entry. */
      if (il_entity != NULL) {
        ielep->entity = canonicalize_tagged_ptr(kind, il_entity);
      } else {
        /* If any list element fails, the entire list is considered invalid. */
        mep->invalid = TRUE;
      }  /* if */
      /* Append the new symbol list entry. */
      ielep->next = (an_il_entity_list_entry_ptr)mep->entity.ptr;
      mep->entity.ptr = (char*)ielep;
      /* Move to the next symbol. */
      overloaded_sym = overloaded_sym->next;
    } while (overloaded_sym != NULL);
  } else {
    an_il_entry_kind kind;
    char             *il_entity = il_entry_for_symbol_null_okay(sym, &kind);

    mep->imminent = TRUE;
    if (il_entity != NULL) {
      mep->entity = canonicalize_tagged_ptr(kind, il_entity);
    } else {
      mep->invalid = TRUE;
    }  /* if */
  }  /* if */
  if (!mep->invalid) {
    if (is_class_struct_union_symbol(sym) &&
        decl_idx.sort == ifc_ds_decl_scope) {
      /* Check for a scope declaration with a pending definition that is not
         yet mapped. */
      an_ifc_decl_scope scope_decl={0};

      /* To construct the tokens preceding the tok_ifc_decl, the corresponding
         IFC node must have been previously used successfully; thus, it's safe
         to directly construct. */
      construct_node_prechecked(&scope_decl, decl_idx);

      an_ifc_reachable_properties_bitfield properties =
                                                get_ifc_properties(scope_decl);

      if (test_bitmask_ifc_rpb_initializer(properties)) {
        /* Record the presence of a definition. */
        an_il_entry_kind kind;
        char             *il_entity = il_entry_for_symbol(sym, &kind);

        /* This assertion should hold: as we've already checked that we're
           working with a type symbol, the corresponding IL entity should
           always be a type. */
        check_assertion(kind == iek_type);

        a_type_ptr type = (a_type_ptr)il_entity;
        if (!a_lazy_entity_part_has_associated_ifc_decl(ifc_tag_definitions,make_tagged_ptr(type))) {
          a_lazy_entity_part_associate_entity(ifc_tag_definitions,make_tagged_ptr(type),decl_idx);
        }  /* if */
      }  /* if */
    }  /* if */
    if (sym->is_class_member || is_local_variable_symbol(sym)) {
      mep->scope = scope_stack[decl_scope_level].il_scope;
#if CHECKING
      /* FIXME: We don't know how to resolve the home scope on some class
         member declarations that can end up here (hence the check for
         has_ifc_home_scope).  While this isn't (strictly speaking) a problem,
         it does pose an issue for the validation logic that follows. */
      /* FIXME: Similarly for members of nested classes and explicit class
         template specialization, we can't properly compute the scope from the
         decl idx resulting in a spuriously failing comparison. */
      if (sym->is_class_member && has_ifc_home_scope(decl_idx) &&
          !is_nested_class_member(mep) &&
          !is_in_explicit_specialization(mep)) {
        /* FIXME: When the parent scope has a mep marked invalid, the result of
           get_home_scope is NULL.  Should this be propagated to this module
           entity?  Should this is even be "allowed" to happen at this point
           the program? */
        check_assertion(mep->scope == get_home_scope_an_ifc_decl_index(decl_idx) ||
                        get_home_scope_an_ifc_decl_index(decl_idx) == NULL);
      }  /* if */
#endif /* CHECKING */
    } else if (is_hidden_friend_an_ifc_decl_index(decl_idx)) {
      a_scope_stack_entry_ptr ssep = &scope_stack[decl_scope_level];

      while (ssep->kind != sck_file && ssep->kind != sck_namespace) {
        ssep = &scope_stack[ssep->previous_scope];
      }  /* while */
      mep->scope = ssep->il_scope;
    } else {
      expect_error_str("the given entity should've been processed by "
                       "process_declaration_to_il_entity instead of using "
                       "tok_ifc_decl");
    }  /* if */
    finish_mep_processing(mep);
  }  /* if */
}  /* record_symbol_for_ifc_decl */





static a_boolean init_locator_from_name_an_ifc_text_offset(an_ifc_text_offset            ref,
                                        const an_ifc_source_location locus,
                                        a_symbol_locator             *loc)
/*
Initialize the locator specified by loc.  The name of the entity is the textual
name associated with the given reference.  The source position is given by
locus.  Return TRUE if initialization was completed and the locator is usable
(i.e., the given reference and locus were valid for locator initialization),
otherwise return FALSE.

FIXME: Not sure if we need source location here.
*/
{
  a_boolean         result = FALSE;
  a_source_position pos;

  if (source_position_from_locus(&pos, locus)) {
    clear_locator(loc, &pos);

    Opt_a_string opt_name=name_from_index_an_ifc_text_offset(ref,loc);
    /* If a name is present, and this declaration isn't anonymous, initialize a
       locator for it. */
    if ((opt_name).has_value && !((opt_name).value).len==0) {
      a_string *name = &((opt_name).value);

      if (!loc->is_operator_name &&
          !loc->is_conversion_name &&
          !loc->is_udl_operator_name) {
        if (identifier_is_valid(edg_string_chars(&((*name))))) {
          /* Find the symbol (if not a special or error case). */
          (void)find_symbol(edg_string_chars(&((*name))), ((*name)).len, loc);
        } else {
          pos_error(ec_ifc_bad_identifier, &pos, edg_string_chars(&((*name))));
          { ifc_opt_string_destroy((Opt_a_string*)&opt_name); goto done; }
        }  /* if */
      }  /* if */
      /* Initialization was completed successfully. */
      result = TRUE;
    }  /* if */
  
ifc_opt_string_destroy((Opt_a_string*)&opt_name);
}  /* if */
done:
  return result;
}  /* init_locator_from_name */


  /* init_decl_locator */


static inline a_boolean init_decl_locator_an_ifc_decl_alias(const an_ifc_decl_alias decl,
                                          a_symbol_locator       *loc)
/*
Initialize the locator specified by loc for the declaration represented at decl
using a NameIndex-derived declaration name.  Return TRUE if processing
succeeded, otherwise return FALSE.
*/
{
  a_boolean result = FALSE;

  if (has_ifc_name(decl) && has_ifc_locus(decl)) {
    /* name_idx can be typed an_ifc_text_offset or an_ifc_name_index, use auto
       to capture this flexibility (at least until we allow text_offset
       to automatically convert into name_index). */
    an_ifc_text_offset name_idx=get_ifc_name(decl);
    an_ifc_source_location locus = get_ifc_locus(decl);

    result = init_decl_locator_an_ifc_text_offset(name_idx,locus,loc);
  }  /* if */
  return result;
}

