      ifc_cache_token(cache,tok_using,NULL);
      cache_expr(cache, parent, cinfo);
      ifc_cache_token(cache,tok_colon_colon,NULL);
      cache_identifier(cache,edg_string_chars(&((*decl_name))),NULL);
