          ifc_cache_token(cache,tok_using,NULL);
          cache_identifier(cache,edg_string_chars(&((*decl_name))),NULL);
          ifc_cache_token(cache,tok_assign,NULL);
          cache_token_with_index_an_ifc_decl_index(cache,tok_ifc_decl_ref,resolution);
