a_boolean load_variable_initializer_from_ifc_module(a_variable_ptr vp)
/*
The given variable claims to have an initializer in a currently-imported IFC
module; process said initializer and return TRUE.  If problems are encountered
during processing, return FALSE.

The presence of a variable initializer should be checked for via
has_variable_initializer_from_ifc_module prior to attempting to load the
variable initializer.
*/
{
  a_boolean result = FALSE;

  check_assertion(has_variable_initializer_from_ifc_module(vp));
  if (a_lazy_entity_part_can_be_processed(ifc_var_inits,make_tagged_ptr(vp))) {
    an_ifc_decl_index
                decl_idx = a_lazy_entity_part_get_associated_ifc_decl(ifc_var_inits,make_tagged_ptr(vp));
    a_module_entity_ptr
                mep = get_ifc_module_entity(decl_idx);
    a_module_entity_stack_state mep_state={0}; a_module_entity_stack_state_init(&mep_state,mep);
    a_diagnostic_suppression diag_suppress={0}; edg_diagnostic_suppression_init(&diag_suppress,&input_state_for(decl_idx)->suppressed_diagnostics,!display_module_import_diagnostics);

#if DEBUG
    if (db_flag_is_set("ifc_idx")) {
      a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"Variable initializer loading started for "); { a_string _ifc_owned_piece=(index_to_str_an_ifc_decl_index(decl_idx)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } _ifc_string_result; });

      edg_string_print(&(err_msg),f_debug,"\n");
    
edg_string_destroy((a_string*)&err_msg);
}  /* if */
#endif /* DEBUG */

    a_module_scope_push_kind
                scope_push_status = mspk_unattempted;
    push_module_declaration_context(mep->scope, &scope_push_status);
    a_lazy_entity_part_mark_pending(ifc_var_inits,make_tagged_ptr(vp));

    Opt_an_ifc_decl_variable opt_var_decl={0};
    construct_node(&opt_var_decl, decl_idx);
    if ((opt_var_decl).has_value) {
      an_ifc_decl_variable
                var_decl = (opt_var_decl).value;
      an_ifc_expr_index
                init = get_ifc_initializer(var_decl);

      /* Determine the init procedure to use; this will be either a direct
         constant synthesis from the IFC representation or an initializer
         parsed from tokens. */
      if (init.sort == ifc_es_expr_product_type_value) {
        /* The initialization is a constant value (roughly equivalent to the
           EDG front end's initk_static from a ck_aggregate constant). */
        /* The variable should always be constexpr if it's an
           ExprSort::ProductTypeValue value. */
        check_assertion(is_var_constexpr_an_ifc_decl_variable(var_decl));
        vp->is_constexpr = TRUE;

        an_ifc_object_traits_bitfield
                traits = get_ifc_traits(var_decl);
        if (test_bitmask_ifc_otb_inline(traits)) {
          vp->is_inline = TRUE;
        }  /* if */

        /* Load the constant itself. */
        a_constant_ptr
                init_constant = load_product_type_value_constant(init);
        if (!is_error_constant(init_constant)) {
          /* Configure the variable for the given initializing constant. */
          vp->init_kind = initk_static;
          vp->initializer.constant = init_constant;
          vp->has_explicit_initializer = TRUE;
          vp->constant_valued = TRUE;
          /* Mark this as a successful load. */
          result = TRUE;
        }  /* if */
      } else {
        a_module_token_cache init_cache={0}; a_module_token_cache_init(&init_cache,NULL);

        cache_expr(&init_cache, init, /*cinfo=*/(an_ifc_cache_info){0});
#if DEBUG
        if (db_flag_is_set("ifc_def")) {
          fprintf(f_debug, "Variable initializer cache:\n");
          db_tokens(a_module_token_cache_as_canonical(&init_cache));
          fprintf(f_debug, "\n---------------------\n");
        }  /* if */
#endif /* DEBUG */
        if (a_module_token_cache_is_valid(&(init_cache))) {
          an_ifc_object_traits_bitfield
                traits = get_ifc_traits(var_decl);

          if (test_bitmask_ifc_otb_inline(traits)) {
            vp->is_inline = TRUE;
          }  /* if */
          if (is_var_constexpr_an_ifc_decl_variable(var_decl)) {
            vp->is_constexpr = TRUE;
          }  /* if */

          a_module_entity_rescan rescan={0}; a_module_entity_rescan_init(&rescan,&init_cache,NULL);
          a_boolean
                paren_flag = curr_token == tok_lparen;
          /* If the initial token is a paren, set the paren flag and consume
             the opening paren. */
          if (paren_flag) {
            (void)get_token();
          }  /* if */

          a_decl_parse_state
                dps;
          a_decl_pos_block
                decl_pos_block;
          a_boolean
                incomplete_type_err = FALSE;
          init_decl_parse_state(&dps);
          dps.sym = symbol_for(vp);

          /* Convert the name linkage back to an id linkage. */
          /* FIXME: Is this right/should this be extracted? */
          an_id_linkage_kind
                id_linkage = idl_none;
          switch (vp->source_corresp.name_linkage) {
            case nlk_none:
              id_linkage = idl_none;
              break;
            case nlk_internal:
              id_linkage = idl_internal;
              break;
            case nlk_cplusplus_external:
            case nlk_external:
              id_linkage = idl_external;
              break;
            case nlk_last:
              /* This should not show up from a source correspondence. */
              unexpected_condition();
            /* Implementations with custom linkage kinds must pick the
               appropriate id linkage kind. */
            default_is_unexpected();
          }  /* switch */
          initializer(&dps, &null_source_position, id_linkage,
                      paren_flag, &incomplete_type_err, &decl_pos_block);
          if (vp->init_kind != initk_none) {
            result = TRUE;
          }  /* if */
        
a_module_entity_rescan_destroy((a_module_entity_rescan*)&rescan);
}  /* if */
      
a_module_token_cache_destroy((a_module_token_cache*)&init_cache);
}  /* if */
    }  /* if */
    /* Mark the success or failure of the initializer load so we don't reenter
       this branch. */
    if (result) {
      a_lazy_entity_part_mark_finished(ifc_var_inits,make_tagged_ptr(vp));
      /* Update the symbol to note the definition was loaded. */
      symbol_for(vp)->defined = TRUE;
    } else {
      a_lazy_entity_part_mark_failure(ifc_var_inits,make_tagged_ptr(vp));
      diagnose_ifc_entity_part_load_failure_an_ifc_decl_index(ec_ifc_initializer_load_failure,symbol_for(vp),decl_idx);
    }  /* if */
    pop_module_declaration_context(scope_push_status);
#if DEBUG
    if (db_flag_is_set("ifc_idx")) {
      a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"Variable initializer loading done for "); { a_string _ifc_owned_piece=(index_to_str_an_ifc_decl_index(decl_idx)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } _ifc_string_result; });

      edg_string_print(&(err_msg),f_debug,"\n");
    
edg_string_destroy((a_string*)&err_msg);
}  /* if */
#endif /* DEBUG */
  
edg_diagnostic_suppression_destroy((a_diagnostic_suppression*)&diag_suppress);
a_module_entity_stack_state_destroy((a_module_entity_stack_state*)&mep_state);
}  /* if */
  return result;
}  /* load_variable_initializer_from_ifc_module */


a_boolean has_routine_definition_from_ifc_module(a_routine_ptr  rp)
/*
If the given routine has a definition in a currently-imported IFC module
return TRUE.
*/
{
  return a_lazy_entity_part_has_associated_ifc_decl(ifc_function_bodies,make_tagged_ptr(rp));
}  /* has_routine_definition_from_ifc_module */





a_boolean load_routine_definition_from_ifc_module(a_routine_ptr  rp)
/*
The given routine claims to have a definition in a currently-imported IFC
module; process said definition and return TRUE.  If problems are encountered
during processing, return FALSE.

The presence of a routine definition should be checked for via
has_routine_definition_from_ifc_module prior to attempting to load the routine
definition.
*/
{
  a_boolean result = FALSE;

  check_assertion(has_routine_definition_from_ifc_module(rp));
  if (a_lazy_entity_part_can_be_processed(ifc_function_bodies,make_tagged_ptr(rp))) {
    an_ifc_decl_index           decl_idx =
                              a_lazy_entity_part_get_associated_ifc_decl(ifc_function_bodies,make_tagged_ptr(rp));
    a_module_token_cache def_cache={0}; a_module_token_cache_init(&def_cache,NULL);
    a_module_entity_ptr         mep = get_ifc_module_entity(decl_idx);
    a_module_entity_stack_state mep_state={0}; a_module_entity_stack_state_init(&mep_state,mep);
    a_diagnostic_suppression diag_suppress={0}; edg_diagnostic_suppression_init(&diag_suppress,&input_state_for(decl_idx)->suppressed_diagnostics,!display_module_import_diagnostics);

#if DEBUG
    if (db_flag_is_set("ifc_idx")) {
      a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"Function def loading started for "); { a_string _ifc_owned_piece=(index_to_str_an_ifc_decl_index(decl_idx)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } _ifc_string_result; });

      edg_string_print(&(err_msg),f_debug,"\n");
    
edg_string_destroy((a_string*)&err_msg);
}  /* if */
#endif /* DEBUG */
    a_lazy_entity_part_mark_pending(ifc_function_bodies,make_tagged_ptr(rp));

    a_module_scope_push_kind scope_push_status = mspk_unattempted;
    an_ifc_decl_index        enclosing_ifc_ns_scope =
                                   get_ifc_enclosing_namespace_scope(decl_idx);
    a_scope_ptr              enclosing_ns_scope =
                                             get_scope(enclosing_ifc_ns_scope);
    if (enclosing_ns_scope != NULL) {
      an_ifc_cache_info cache_info={0}; an_ifc_cache_info_init(&cache_info);

      ensure_module_scope_a_scope_ptr(enclosing_ns_scope,&scope_push_status);
      cache_info.lexical_scope = enclosing_ifc_ns_scope;
      cache_info.ignore_default_arguments = TRUE;
      cache_decl(&def_cache, decl_idx, cache_info);
      if (a_module_token_cache_is_valid(&(def_cache))) {
        an_il_entry_kind kind;
        char             *il_entity = parse_cached_nonmember_decl(&def_cache,
                                                                  &kind);

        if (il_entity != NULL) {
          /* We have successfully loaded the definition. */
          mep->entity = canonicalize_tagged_ptr(kind, il_entity);
          a_lazy_entity_part_mark_finished(ifc_function_bodies,make_tagged_ptr(rp));
          result = TRUE;
          goto loaded_successfully;
        }  /* if */
      }  /* if */
    }  /* if */
    a_lazy_entity_part_mark_failure(ifc_function_bodies,make_tagged_ptr(rp));
    diagnose_ifc_entity_part_load_failure_an_ifc_decl_index(ec_ifc_definition_load_failure,symbol_for(rp),decl_idx);
loaded_successfully:
    if (scope_push_status != mspk_unattempted) {
      pop_module_declaration_context(scope_push_status);
    }  /* if */
#if DEBUG
    if (db_flag_is_set("ifc_idx")) {
      a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"Function def loading done for "); { a_string _ifc_owned_piece=(index_to_str_an_ifc_decl_index(decl_idx)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } _ifc_string_result; });

      edg_string_print(&(err_msg),f_debug,"\n");
    
edg_string_destroy((a_string*)&err_msg);
}  /* if */
#endif /* DEBUG */
  
edg_diagnostic_suppression_destroy((a_diagnostic_suppression*)&diag_suppress);
a_module_entity_stack_state_destroy((a_module_entity_stack_state*)&mep_state);
a_module_token_cache_destroy((a_module_token_cache*)&def_cache);
}  /* if */
  return result;
}  /* load_routine_definition_from_ifc_module */


static Opt_an_ifc_decl_index decl_index_from_type_index(
                                                    an_ifc_type_index type_idx)
/*
Given a type index, return the underlying declaration index declaring the type;
if the type is not declared by a declaration, return an empty optional.
*/
{
  Opt_an_ifc_decl_index result={0};

  type_idx = remove_type_qualifiers(type_idx);
  if (type_idx.sort == ifc_ts_type_designated) {
    Opt_an_ifc_type_designated opt_designated_type={0};

    construct_node(&opt_designated_type, type_idx);
    if ((opt_designated_type).has_value) {
      an_ifc_type_designated designated_type = (opt_designated_type).value;

      result = (Opt_an_ifc_decl_index){TRUE,get_ifc_decl(designated_type)};
    }  /* if */
  }  /* if */
  return result;
}  /* decl_index_from_type_index */


static a_type_kind type_kind_for_type_index(an_ifc_type_index type_idx)
/*
Given a type index, return the corresponding type kind.
*/
{
  a_type_kind      result = tk_unknown;
  an_ifc_type_sort sort = type_idx.sort;

  switch (sort) {
    case ifc_ts_type_fundamental:
      { Opt_an_ifc_type_fundamental opt_itf={0};

        construct_node(&opt_itf, type_idx);
        if (!(opt_itf).has_value) {
          goto invalid;
        }  /* if */

        an_ifc_type_fundamental itf = (opt_itf).value;
        an_ifc_type_basis_sort  basis = get_ifc_basis(itf);
        switch (basis) {
          case ifc_tbs_ellipsis:
          case ifc_tbs_auto:
          case ifc_tbs_decltype_auto:
          case ifc_tbs_namespace:
          case ifc_tbs_interface:
          case ifc_tbs_segment_type:
          case ifc_tbs_empty:
          case ifc_tbs_concept:
            { a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"Unexpected "); edg_string_append_cstr(&_ifc_string_result,str_for_an_ifc_type_basis_sort(basis)); _ifc_string_result; });

              ifc_unexpected(module_of(itf), err_msg);
            
edg_string_destroy((a_string*)&err_msg);
}
            goto invalid;
          case ifc_tbs_void:
            result = tk_void;
            break;
          case ifc_tbs_bool:
          case ifc_tbs_char:
          case ifc_tbs_wchar_t:
          case ifc_tbs_int:
            result = tk_integer;
            break;
          case ifc_tbs_float:
          case ifc_tbs_double:
            result = tk_float;
            break;
          case ifc_tbs_nullptr:
            result = tk_nullptr;
            break;
          case ifc_tbs_class:
            result = tk_class;
            break;
          case ifc_tbs_struct:
            result = tk_struct;
            break;
          case ifc_tbs_union:
            result = tk_union;
            break;
          case ifc_tbs_enum:
            result = tk_enum;
            break;
          case ifc_tbs_typename:
            result = tk_typeref;
            break;
          case ifc_tbs_function:
          case ifc_tbs_overload:
            result = tk_routine;
            break;
          case ifc_tbs_variable_template:
            result = tk_unknown;
            break;
          default_is_unexpected_str("Unexpected TypeBasis kind");
        }  /* switch */
      }
      break;
    default:
      { a_type_ptr type = type_for_type_index(type_idx);

        result = type->kind;
      }
      break;
  }  /* switch */
invalid:;
  return result;
}  /* type_kind_for_type_index */


static a_boolean type_represents_type_templ_param_ref(
                                                    an_ifc_type_index type_idx)
/*
Given a type index, return TRUE if the type index represents a type template
parameter.
*/
{
  /* This function does not work for EDG-authored IFC files.  The caller should
     have used param_represents_type_templ_param_ref. */
  check_assertion(!is_edg_authored(type_idx));
  a_boolean result = FALSE;

  if (type_idx.sort == ifc_ts_type_expansion) {
    Opt_an_ifc_type_expansion opt_expansion_type={0};

    construct_node(&opt_expansion_type, type_idx);
    if ((opt_expansion_type).has_value) {
      an_ifc_type_expansion expansion_type = (opt_expansion_type).value;
      an_ifc_type_index     pack = get_ifc_pack(expansion_type);

      type_idx = pack;
    }  /* if */
  }  /* if */
  if (type_idx.sort == ifc_ts_type_fundamental) {
    Opt_an_ifc_type_fundamental opt_itf={0};

    construct_node(&opt_itf, type_idx);
    if ((opt_itf).has_value) {
      an_ifc_type_fundamental itf = (opt_itf).value;
      an_ifc_type_basis_sort  basis = get_ifc_basis(itf);

      result = basis == ifc_tbs_typename;
    }  /* if */
  }  /* if */
  return result;
}  /* type_represents_type_templ_param_ref */


static a_boolean param_represents_type_templ_param_ref(
                                      const an_ifc_decl_parameter param_decl)
/*
Given an IFC parameter declaration, return TRUE if the type index represents a
type template parameter.
*/
{
  a_boolean result = FALSE;

  if (is_edg_authored(param_decl)) {
    if (get_ifc_sort(param_decl) == ifc_ps_type) {
      result = TRUE;
    }  /* if */
  } else {
    an_ifc_type_index type_idx = get_ifc_type(param_decl);

    if (type_represents_type_templ_param_ref(type_idx)) {
      result = TRUE;
    }  /* if */
  }  /* if */
  return result;
}  /* param_represents_type_templ_param_ref */



/*
A stack used to traverse symbol lists that may contain symbols with their own
"nested" lists that additionally need traversed (e.g., sk_overload_function).
*/
struct a_symbol_traversal_stack {
ifc_Small_dyn_array_a_symbol_ptr_2
                traversal_stack;

a_symbol_ptr traversal_stack_buffer[2];
};

static void a_symbol_traversal_stack_init(a_symbol_traversal_stack *self, a_symbol_ptr sym_list)
{
memset(self,0,sizeof(*self));
edg_array_init_buffer(&self->traversal_stack,sizeof(a_symbol_ptr),EDG_ALLOC_FE,0,NULL,NULL,self->traversal_stack_buffer,2);

 a_symbol_traversal_stack_push_symbol_if_non_null(self,sym_list); }

static a_boolean a_symbol_traversal_stack_has_next(a_symbol_traversal_stack *self)
{ return !(&(self->traversal_stack))->len==0; };  /* a_symbol_traversal_stack */


static a_symbol_ptr a_symbol_traversal_stack_next(a_symbol_traversal_stack *self)
{
  check_assertion(a_symbol_traversal_stack_has_next(self));
  a_symbol_ptr elem = (*(a_symbol_ptr *)edg_array_at(&(self->traversal_stack),(&(self->traversal_stack))->len-1));

  edg_array_remove(&(self->traversal_stack),(&(self->traversal_stack))->len-1,1);
  /* Push the next element in this list. */
  a_symbol_traversal_stack_push_symbol_if_non_null(self,elem->next);
  /* Expand any sub lists, replacing the element with the first element of that
     list. */
  if (elem->kind == sk_overloaded_function) {
    elem = elem->variant.overloaded_function.symbols;
    /* Push the next element in expanded list, resulting in its traversal,
       before returning to the parent traversal. */
    a_symbol_traversal_stack_push_symbol_if_non_null(self,elem->next);
  }  /* if */
  return elem;
}  /* a_symbol_traversal_stack::next */


static void a_symbol_traversal_stack_push_symbol_if_non_null(a_symbol_traversal_stack *self, a_symbol_ptr sym)
{
  if (sym != NULL) {
    IFC_ARRAY_PUSH(&(self->traversal_stack),a_symbol_ptr,sym);
  }  /* if */
}  /* a_symbol_traversal_stack::push_symbol_if_non_null */

  /* namespace */

static a_boolean
is_redeclared_basic_entity(a_symbol            *sym,
                           a_module_entity_ptr mep,
                           an_il_entry_kind    expected_kind,
                           char                **redecl_entity,
                           an_il_entry_kind    *redecl_kind)
/*
For a given module entity's potentially previously declared symbol, module
entity pointer, and expected kind, check to see if the symbol is indeed a
redeclaration.  If the symbol is a redeclaration, return TRUE and set
*redecl_entity and *redecl_kind to the redeclared entity and its associated
kind; otherwise, return FALSE.
*/
{
  a_boolean    result = FALSE;
  a_module_ptr sym_mod = lookup_module_for_symbol(sym);
  a_module_ptr mep_mod = lookup_module_for_mep(mep);

  if (sym_mod == mep_mod) {
    an_il_entry_kind kind;
    char             *entity = il_entry_for_symbol_null_okay(sym, &kind);

    if (entity != NULL && kind == expected_kind) {
      a_source_correspondence_ptr scp =
                                     source_corresp_for_il_entry(entity, kind);

      if (scp != NULL) {
        a_scope_ptr scope = get_parent_scope_of(scp);

        if (mep->scope == scope) {
          *redecl_entity = entity;
          *redecl_kind = kind;
          result = TRUE;
        }  /* if */
      }  /* if */
    }  /* if */
  }  /* if */
  return result;
}  /* is_redeclared_basic_entity */


static a_boolean
find_redeclared_basic_entity_in_list(a_symbol            *sym_list,
                                     a_module_entity_ptr mep,
                                     an_il_entry_kind    expected_kind,
                                     char                **redecl_entity,
                                     an_il_entry_kind    *redecl_kind)
/*
For a given module entity's associated symbol list, module entity pointer, and
expected kind, search the symbols for a redeclaration.  If a redeclaration is
found, return TRUE and set *redecl_entity and *redecl_kind to the redeclared
entity and its associated kind; otherwise, return FALSE.

This function should not be used directly in modules code, instead see
check_and_set_redeclaration.
*/
{
  a_boolean                result = FALSE;
  a_symbol_traversal_stack traverser={0};
  a_symbol_traversal_stack_init(&traverser,sym_list);

  while (a_symbol_traversal_stack_has_next(&(traverser))) {
    a_symbol_ptr sym = a_symbol_traversal_stack_next(&(traverser));

    if (is_redeclared_basic_entity(sym, mep, expected_kind, redecl_entity,
                                   redecl_kind)) {
      result = TRUE;
      break;
    }  /* if */
  }  /* while */
  { a_boolean _ifc_return_value=(result); a_symbol_traversal_stack_destroy((a_symbol_traversal_stack*)&traverser); return _ifc_return_value; }

a_symbol_traversal_stack_destroy((a_symbol_traversal_stack*)&traverser);
}  /* find_redeclared_basic_entity_in_list */


static a_boolean
find_redeclared_basic_entity(a_symbol_header     *sym_header,
                             a_module_entity_ptr mep,
                             an_il_entry_kind    expected_kind,
                             char                **redecl_entity,
                             an_il_entry_kind    *redecl_kind)
/*
For a given module entity's symbol header, module entity pointer, and expected
kind, search the active and inactive symbols for a redeclaration.  If a
redeclaration is found, return TRUE and set *redecl_entity and *redecl_kind to
the redeclared entity and its associated kind; otherwise, return FALSE.

This function should not be used directly in modules code, instead see
check_and_set_redeclaration.
*/
{
  a_boolean    result = FALSE;
  a_symbol_ptr active_symbols = sym_header->symbol;
  a_symbol_ptr inactive_symbols = sym_header->inactive_symbols;

  if (find_redeclared_basic_entity_in_list(active_symbols, mep, expected_kind,
                                           redecl_entity, redecl_kind) ||
      find_redeclared_basic_entity_in_list(inactive_symbols, mep,
                                           expected_kind, redecl_entity,
                                           redecl_kind)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* find_redeclared_basic_entity */


