    /* When this condition is violated, the entity was not marked invalid,
       but it also wasn't completed.  Either the IL entity was not correctly
       set, or the entity should've been marked invalid. */
    a_string err_msg=({ a_string _ifc_string_result; edg_string_init_small(&_ifc_string_result,EDG_ALLOC_FE); edg_string_append_cstr(&_ifc_string_result,"processing of "); { a_string _ifc_owned_piece=(index_to_str_an_ifc_decl_index(mep_idx)); edg_string_append_view(&_ifc_string_result,edg_string_as_view(&_ifc_owned_piece));edg_string_destroy(&_ifc_owned_piece); } edg_string_append_cstr(&_ifc_string_result," did not set the IL entity or mark the"
                              " entity invalid"); _ifc_string_result; });

