a_boolean has_type_definition_from_ifc_module(a_type_ptr  ty)
/*
If the given type has a definition in a currently-imported IFC module return
TRUE.
*/
{
  return a_lazy_entity_part_has_associated_ifc_decl(ifc_tag_definitions,make_tagged_ptr(ty));
}  /* has_type_definition_from_ifc_module */


a_boolean load_type_definition_from_ifc_module(a_type_ptr  ty)
/*
The given type claims to have a definition in a currently-imported IFC module;
process said definition and return TRUE.  If problems are encountered during
processing, return FALSE.

The presence of a type definition should be checked for via
has_type_definition_from_ifc_module prior to attempting to load the type
definition.
*/
{
  check_assertion(has_type_definition_from_ifc_module(ty));
  an_ifc_decl_index
                def_idx = a_lazy_entity_part_get_associated_ifc_decl(ifc_tag_definitions,make_tagged_ptr(ty));
  a_module_entity_ptr
                def_mep = get_ifc_module_entity(def_idx);

  if (a_lazy_entity_part_can_be_processed(ifc_tag_definitions,make_tagged_ptr(ty))) {
    a_module_scope_push_kind scope_push_status = mspk_unattempted;

    a_lazy_entity_part_mark_pending(ifc_tag_definitions,make_tagged_ptr(ty));
    push_module_declaration_context(def_mep->scope, &scope_push_status);
    complete_definition_of_module_class(def_mep);
    pop_module_declaration_context(scope_push_status);
    if (def_mep->invalid) {
      a_lazy_entity_part_mark_failure(ifc_tag_definitions,make_tagged_ptr(ty));
      diagnose_ifc_entity_part_load_failure_an_ifc_decl_index(ec_ifc_definition_load_failure,symbol_for(ty),def_idx);
    } else {
      a_lazy_entity_part_mark_finished(ifc_tag_definitions,make_tagged_ptr(ty));
    }  /* if */
  }  /* if */
  return !def_mep->invalid;
}  /* load_type_definition_from_ifc_module */


a_module_entity_ptr locate_ifc_module_entity(a_module_entry_locator loc)
/*
Return the module entity pointer associated with the given module entry
locator.
*/
{
  /* If this assertion fails a module entity pointer that's not from an IFC
     file was incorrectly passed to this function. */
  check_assertion(loc.kind == melk_ifc);
  a_module_entity_ptr   result = NULL;
  an_ifc_partition_kind part_kind = loc.variant.ifc.partition;

  if (is_decl_sort_an_ifc_partition_kind(part_kind)) {
    an_ifc_decl_index decl_idx = decl_index_of_a_module_entry_locator(loc);

    result = get_ifc_module_entity(decl_idx);
  } else {
    unexpected_condition_str("unexpected call to locate_ifc_module_entity "
                             "with a non-declaration entity");
  }  /* if */
  return result;
}  /* locate_ifc_module_entity */


void load_namespace_elements_from_ifc_locator(a_module_entity_ptr    mep,
                                              a_module_entry_locator loc)
/*
Load the namespace elements specified by the given IFC module entry locator
for the namespace represented by the given module entity.
*/
{
  /* This function should only be called for namespace IL entities. */
  check_assertion(mep->entity.kind == iek_namespace);
  an_ifc_decl_index      assoc_decl_idx = decl_index_of_a_module_entry_locator(loc);
  Opt_an_ifc_decl_scope opt_assoc_scope_decl={0};

  construct_node(&opt_assoc_scope_decl, assoc_decl_idx);
  if ((opt_assoc_scope_decl).has_value) {
    an_ifc_decl_scope   assoc_scope_decl = (opt_assoc_scope_decl).value;
    an_ifc_scope_offset init = get_ifc_initializer(assoc_scope_decl);
    a_namespace_ptr     nsp = (a_namespace_ptr)mep->entity.ptr;

    load_ifc_namespace(init, nsp->variant.assoc_scope);
  }  /* if */
}  /* load_namespace_elements_from_ifc_locator */





static void update_ifc_declaration(a_module_entity_ptr mep,
                                   an_ifc_decl_index   decl_idx)
/*
A new IFC declaration index has been discovered for the given module entity.
Perform any updates to the entity using the new information.
*/
{
  if (!validate(decl_idx)) {
    goto invalid;
  }  /* if */
  update_mep_origin_flags(mep, decl_idx);
  if (try_mark_definitions(mep, decl_idx)) {
    /* If a definition was marked, mark this locator as the primary locator. */
    a_module_entry_locator loc = module_entry_locator_from_index_an_ifc_decl_index(decl_idx);

    mark_locator_as_primary(mep, loc);
  }  /* if */
  goto done;
invalid:
  mep->invalid = TRUE;
done:;
}  /* update_ifc_declaration */


void update_entity_from_new_ifc_locator(a_module_entity_ptr    mep,
                                        a_module_entry_locator new_loc)
/*
A new IFC locator has been discovered for the given module entity.  Perform
any updates to the entity using the new information.
*/
{
  /* If this assertion fails, the wrong kind of locator was given to this
     function (see update_entity_from_new_locator). */
  check_assertion(new_loc.kind == melk_ifc);
  an_ifc_partition_kind part_kind = new_loc.variant.ifc.partition;

  if (is_decl_sort_an_ifc_partition_kind(part_kind)) {
    an_ifc_decl_index decl_idx = decl_index_of_a_module_entry_locator(new_loc);

    update_ifc_declaration(mep, decl_idx);
  }  /* if */
}  /* update_entity_from_new_ifc_locator */


Opt_a_source_position source_position_from_ifc_of(a_module_entity_ptr mep)
/*
Return the source position of the given module entity pointer if available;
otherwise, return an empty optional.
*/
{
  Opt_a_source_position result={0};
  a_module_entry_locator *primary=&((*(a_module_entry_locator *)edg_array_at(&mep->locators,mep->primary_locator_idx)));

  /* If this assertion fails a module entity pointer that's not from an IFC
     file was incorrectly passed to this function. */
  check_assertion((*primary).kind == melk_ifc);
  if (is_decl_sort_an_ifc_partition_kind((*primary).variant.ifc.partition)) {
    an_ifc_decl_index decl_idx = decl_index_of_a_module_entity_ptr(mep);

    if (validate(decl_idx) && has_ifc_locus(decl_idx)) {
      an_ifc_source_location locus = get_ifc_locus(decl_idx);
      a_source_position      pos;

      source_position_from_locus(&pos, locus);
      result = (Opt_a_source_position){TRUE,pos};
    }  /* if */
  }  /* if */
  return result;
}  /* source_position_from_ifc_of */

