void db_node_at_tsn_a_token_cache_ptr(a_token_cache_ptr        cache,
                    a_token_sequence_number  tsn)
/*
Print diagnostic information about the node identified by a given token (if
any).
*/
{
  a_shared_token dbg_tok = get_cache_token(cache, tsn);

  if (edg_token_is_ifc_reference(dbg_tok)) {
    a_lexical_ifc_index_reference ifc_idx = edg_token_get_ifc_index(dbg_tok);

    switch (ifc_idx.reference_kind) {
      case liik_decl_index:
        db_node_at_idx(from_lexical_index_an_ifc_decl_index(ifc_idx));
        break;
      case liik_expr_index:
        db_node_at_idx(from_lexical_index_an_ifc_expr_index(ifc_idx));
        break;
      case liik_type_index:
        db_node_at_idx(from_lexical_index_an_ifc_type_index(ifc_idx));
        break;
      default_is_unexpected();
    }  /* switch */
  }  /* if */

edg_shared_token_release(dbg_tok);
}  /* db_node_at_tsn */


