void db_locus(const an_ifc_source_location locus)
/*
Print the corresponding file and line number for the source location
(for debugging purposes).
*/
{
  an_ifc_module_file
                *file = (locus).file;
#if USE_MMAP_FOR_MEMORY_REGIONS
  an_ifc_module_file_read_state *read_state=an_ifc_module_file_get_read_state(file);
#endif /* USE_MMAP_FOR_MEMORY_REGIONS */
  a_const_char  *full_name, *diag_file_name;
  a_line_number line_number;
  a_boolean     at_end_of_source;
  a_source_position
                pos;

  diag_file_name = "";
  /* Save global information related to position before calling
     source_position_from_locus. */
#if USE_MMAP_FOR_MEMORY_REGIONS
  unsigned char *save_byte_buffer = read_state->byte_buffer;
  unsigned char *save_buffer_end = read_state->buffer_end;
#else /* !USE_MMAP_FOR_MEMORY_REGIONS */
  long save_seek = ftell(file->f_module);
#endif /* USE_MMAP_FOR_MEMORY_REGIONS */
  source_position_from_locus(&pos, locus);
  /* Restore saved information. */
#if USE_MMAP_FOR_MEMORY_REGIONS
  read_state->byte_buffer = save_byte_buffer;
  read_state->buffer_end = save_buffer_end;
#else /* !USE_MMAP_FOR_MEMORY_REGIONS */
  (void)fseek(file->f_module, save_seek, SEEK_SET);
#endif /* USE_MMAP_FOR_MEMORY_REGIONS */
  if (pos.seq != 0) {
    (void)conv_seq_to_file_and_line(pos.seq, &diag_file_name,
                                    &full_name, &line_number,
                                    &at_end_of_source);
    (void)fprintf(f_debug, "%s: line %lu colmun %lu\n", full_name,
                  (unsigned long) line_number, (unsigned long) pos.column);
  }  /* if */
}  /* db_locus */

#endif /* DEBUG */

static void merge_compatibility_severity(an_error_severity *result,
                                         an_error_severity new_severity)
/*
Update *result with new_severity if new_severity is more severe than *result's
current value.

FIXME: Is there a more general function for this? Should this be generalized?
*/
{
  if (new_severity > *result) {
    *result = new_severity;
  }  /* if */
}  /* merge_compatibility_severity */



/*
This class is a handler intended for use with check_ifc_compatibility.  It's
used to determine the severity of the IFC file's incompatibility.
*/
struct an_ifc_error_severity_checker {
a_boolean     invalid_version_is_warning;
an_error_severity
                severity_level;
};

static void an_ifc_error_severity_checker_init(an_ifc_error_severity_checker *self, a_boolean invalid_version_is_warning_val)
{
memset(self,0,sizeof(*self));
self->invalid_version_is_warning = invalid_version_is_warning_val;
}

static an_error_severity an_ifc_error_severity_checker_severity(an_ifc_error_severity_checker *self)
{ return self->severity_level; }

static a_boolean an_ifc_error_severity_checker_is_diagnosed(an_ifc_error_severity_checker *self)
{ return self->severity_level != es_none; }

static a_boolean an_ifc_error_severity_checker_is_error(an_ifc_error_severity_checker *self)
{ return self->severity_level >= es_error; };  /* an_ifc_error_severity_checker */


static void an_ifc_error_severity_checker_bad_version(an_ifc_error_severity_checker *self, an_ifc_version major_version,
                                                an_ifc_version minor_version)
{
  if (self->invalid_version_is_warning) {
    merge_compatibility_severity(&self->severity_level, es_warning);
  } else {
    merge_compatibility_severity(&self->severity_level, es_catastrophe);
  }  /* if */
}  /* an_ifc_error_severity_checker::bad_version */


static void an_ifc_error_severity_checker_bad_architecture(an_ifc_error_severity_checker *self, 
                                                 an_ifc_architecture_sort arch)
{
  merge_compatibility_severity(&self->severity_level, es_catastrophe);
}  /* an_ifc_error_severity_checker::bad_architecture */


