static a_boolean an_ifc_input_state_open_and_map_ifc_module_file(an_ifc_input_state *self, 
                                           a_module_import_decl_ptr midp,
                                           a_boolean                issue_diag)
{
  a_module_ptr mod = midp->module_info;

  check_assertion(mod != NULL && mod->resolved_file != NULL);

  Opt_an_ifc_module_file opt_file=open_ifc_module_file(mod->resolved_file);
  if ((opt_file).has_value) {
    /* Establish the association between the IFC file and the IFC module
       interface. */
    self->file = alloc_fe_of_type(an_ifc_module_file);
    an_ifc_module_file_init(self->file,opt_file.value.module_kind,TRUE);
    an_ifc_module_file_move(self->file,&opt_file.value);
    an_ifc_module_file_get_read_state(self->file)->input_state = self;
  } else if (issue_diag) {
    /* FIXME: perhaps better error messages here. */
    pos_error(ec_cannot_import_module, &midp->module_name_position,
              mod->resolved_file);
  }  /* if */
  return (opt_file).has_value;
}  /* an_ifc_input_state::open_and_map_ifc_module_file */

#if EXPENSIVE_CHECKING

static a_boolean can_be_eager_loaded(an_ifc_decl_index decl_idx)
/*
Given a declaration index, return TRUE if it can be eagerly loaded; otherwise,
return FALSE.
*/
{
  a_boolean result = TRUE;

  if (in_get_home_scope) {
    /* A get_home_scope call is being processed; avoid infinite recursion. */
    result = FALSE;
  } else if (decl_idx.sort == ifc_ds_decl_function) {
    Opt_an_ifc_decl_function opt_func_decl={0};

    construct_node(&opt_func_decl, decl_idx);
    if ((opt_func_decl).has_value) {
      an_ifc_decl_function func_decl = (opt_func_decl).value;

      /* Hidden friends should not be eagerly loaded. */
      if (is_function_hidden_friend(func_decl)) {
        result = FALSE;
      }  /* if */
    }  /* if */
  }  /* if */
  return result;
}  /* can_be_eager_loaded */

#endif /* EXPENSIVE_CHECKING */

