      an_ifc_heap_expr  second_heap_expr = (opt_second_heap_expr).value;
      an_ifc_expr_index first_expr = get_ifc_value(first_heap_expr);
      an_ifc_expr_index second_expr = get_ifc_value(second_heap_expr);
