    case ifc_sos_less_equal:
      ifc_cache_token(cache,tok_le,NULL);
      break;
    case ifc_sos_greater:
      ifc_cache_token(cache,tok_gt,NULL);
      break;
    case ifc_sos_greater_equal:
      ifc_cache_token(cache,tok_ge,NULL);
      break;
    case ifc_sos_equal_equal:
      ifc_cache_token(cache,tok_eq,NULL);
      break;
    case ifc_sos_exclaim_equal:
      ifc_cache_token(cache,tok_ne,NULL);
      break;
    case ifc_sos_diamond:
      ifc_cache_token(cache,tok_spaceship,NULL);
      break;
    case ifc_sos_plus_equal:
      ifc_cache_token(cache,tok_plus_assign,NULL);
      break;
    case ifc_sos_dash_equal:
      ifc_cache_token(cache,tok_minus_assign,NULL);
