static a_boolean is_out_of_line_cache_an_ifc_decl_constructor(const an_ifc_decl_constructor  decl,
                                      const an_ifc_cache_info cinfo)
/*
Return TRUE if the given declaration is being cached out-of-line; otherwise,
return FALSE.
*/
{
  an_ifc_decl_index home_scope = get_ifc_home_scope(decl);

  return !an_ifc_decl_index_equal(home_scope,cinfo.lexical_scope);
}

