static Opt_an_ifc_decl_parameter a_lazy_ifc_func_param_chart_get(a_lazy_ifc_func_param_chart *self, an_ifc_index_type param_idx)
{
  Opt_an_ifc_decl_parameter result={0};

  if (a_lazy_ifc_func_param_chart_try_load_chart(self)) {
    an_ifc_chart_unilevel uni_chart = (self->opt_node).value;
    an_ifc_index          start_idx = get_ifc_start(uni_chart);
    an_ifc_cardinality    cardinality = get_ifc_cardinality(uni_chart);

    if (param_idx >= (cardinality).value) {
      goto invalid;
    }  /* if */

    /* FIXME: This is a bit of an abuse of the traverser, but the traverser
       provides a much simplified validation scheme vs rolling out all the
       loading code for the element "manually".  We should have a better
       way to get a single element out of a heap. */
    an_ifc_index_type         element_idx = (start_idx).value + param_idx;
    a_decl_parameter_sequence sequence=ifc_node_sequence(input_state_for(start_idx),get_ifc_partition_kind_an_ifc_decl_parameter(),element_idx,1);
    /* coverity[unreachable] */ /* See FIXME above. */
    for(size_t _ifc_iteration_102=0;_ifc_iteration_102<(sequence).cardinality;++_ifc_iteration_102) {
Indexed_an_ifc_decl_parameter indexed_idp=ifc_indexed_an_ifc_decl_parameter(sequence,_ifc_iteration_102);

      if (!(indexed_idp).node_value.has_value) {
        goto invalid;
      }  /* if */

      result = (Opt_an_ifc_decl_parameter){TRUE,(indexed_idp).node_value.value};
      goto done;
    
}  /* if */
  }  /* if */
  goto done;
invalid:
  (result).has_value=FALSE;
done:
  return result;
}  /* a_lazy_ifc_func_param_chart::get */


static a_boolean a_lazy_ifc_func_param_chart_try_load_chart(a_lazy_ifc_func_param_chart *self)
{
  if (!self->node_invalid) {
    if (is_null_index(self->chart_idx)) {
      /* This isn't strictly speaking invalid, it just means we don't have this
         chart; the invalid case prevents reentry if this function is called
         again. */
      goto invalid;
    }  /* if */

    an_ifc_chart_sort chart_sort = self->chart_idx.sort;
    if (chart_sort == ifc_cs_chart_none) {
      /* This isn't strictly speaking invalid, it just means the chart contains
         nothing; the invalid case prevents reentry if this function is called
         again. */
      goto invalid;
    }  /* if */
    if (chart_sort != ifc_cs_chart_unilevel) {
      /* The associated chart index was set to a "real" chart index, but it
         isn't a uni-level chart; so it's not a valid function parameter
         chart. */
      /* FIXME: We may want an error here. */
      goto invalid;
    }  /* if */
    construct_node(&self->opt_node, self->chart_idx);
    if (!(self->opt_node).has_value) {
      goto invalid;
    }  /* if */
  }  /* if */
  goto done;
invalid:
  self->node_invalid = TRUE;
done:
  return (self->opt_node).has_value;
}  /* a_lazy_ifc_func_param_chart::try_load_chart */


static void an_ifc_func_param_context_init_an_ifc_decl_constructor(an_ifc_func_param_context *self, 
                                  an_ifc_decl_index      decl_idx,
                                  const an_ifc_decl_constructor decl,
                                  an_ifc_decl_index      parameterizing_entity)
{
memset(self,0,sizeof(*self));
self->num_params = 0;
self->params_type = get_func_param_type_an_ifc_decl_constructor(decl);
a_lazy_ifc_func_param_chart_init(&self->decl_param_chart,get_ifc_chart(decl));
a_lazy_ifc_func_param_chart_init(&self->def_param_chart,get_func_defition_param_chart_idx(decl_idx));
a_lazy_ifc_func_param_chart_init(&self->msvc_traits_param_chart,get_msvc_trait_func_param_chart_idx(decl_idx));
a_lazy_ifc_func_param_chart_init(&self->parameterizer_msvc_traits_param_chart,
                    get_msvc_trait_func_param_chart_idx(parameterizing_entity));

  self->num_params = an_ifc_func_param_context_determine_param_count(self);
}

