{
  an_ifc_edg_token_basic_offset
                basic_token_offset = get_ifc_tokens(token_cache);
  an_ifc_cardinality
                num_basic_tokens = get_ifc_num_tokens(token_cache);
  an_edg_token_basic_sequence basic_token_sequence=ifc_node_sequence(input_state_for(basic_token_offset),get_ifc_partition_kind_an_ifc_edg_token_basic(),basic_token_offset.value,(num_basic_tokens).value);

  return basic_token_sequence;
}  /* get_edg_basic_token_sequence */


