static void cache_syntactic_type_qualifiers(
                                          a_module_token_cache_ptr  cache,
                                          an_ifc_qualifier_bitfield qualifiers)
/*
Cache the qualifiers for a syntactically-represented IFC type.
*/
{
  if (test_bitmask_ifc_qb_const(qualifiers)) {
    ifc_cache_token(cache,tok_const,NULL);
  }  /* if */
  if (test_bitmask_ifc_qb_volatile(qualifiers)) {
    ifc_cache_token(cache,tok_volatile,NULL);
  }  /* if */
  if (test_bitmask_ifc_qb_restrict(qualifiers)) {
    ifc_cache_token(cache,tok_restrict,NULL);
  }  /* if */
}  /* cache_syntactic_type_qualifiers */


