static void db_diff_decls(an_ifc_decl_index old_decl_idx,
                          an_ifc_decl_index new_decl_idx)
/*
Given an old IFC declaration index and a new IFC declaration index, compare
and print the diff of the cached tokens.
*/
{
  a_module_token_cache prev_cache={0}; a_module_token_cache_init(&prev_cache,NULL);
  a_module_token_cache new_cache={0}; a_module_token_cache_init(&new_cache,NULL);
  an_ifc_cache_info cinfo={0}; an_ifc_cache_info_init(&cinfo);

  cache_decl(&prev_cache, old_decl_idx, cinfo);
  cache_decl(&new_cache, new_decl_idx, cinfo);
  db_diff_token_caches(a_module_token_cache_as_canonical(&(prev_cache)), a_module_token_cache_as_canonical(&(new_cache)));

a_module_token_cache_destroy((a_module_token_cache*)&new_cache);
a_module_token_cache_destroy((a_module_token_cache*)&prev_cache);
}  /* db_diff_decls */

